d"},"code":"requires_location","device":null,"source":"not_applicable"},{"admin":{"de":"Gastzugang abgelaufen – alles gesperrt","en":"Guest access expired – everything blocked"},"code":"access_expired","device":{"de":"Dein Gastzugang ist abgelaufen","en":"Your guest access has expired"},"source":"access_expired"}],"rules":[{"boundaries":[],"default":false,"default_fixed":false,"default_user_choice":false,"enforcement":"ha","enforcement_with_checked_path":null,"enforcement_with_hub_path":null,"fixed_checkbox":true,"group":"access","help":{"de":"Steuert Home Assistant auch ausserhalb des Heimnetzes. Mit Kindersicherung gelten die Kinderregeln auch unterwegs. Mit „Nur über den Hub“ bekommt das Gerät dafür einen Home-Assistant-Schlüssel, der nur lesen darf.","en":"Controls Home Assistant also outside the home network. With parental controls the kids rules apply away from home too. With “Hub only” the device then gets a read-only Home Assistant key."},"key":"remote_access","label":{"de":"Von unterwegs steuern","en":"Remote access"},"loosening_warning":{"de":"Wer das Gerät in der Hand hat, kann dann von überall dein Zuhause steuern.","en":"Whoever holds the device can then control your home from anywhere."},"order":[false,true],"platforms":["ios","ipados","tvos","watchos","android","android_tablet","android_tv","wearos"],"prerequisite":null,"pro":false,"profile_kinds":null,"replaces":["remote_allowed"],"requires_child_protection":false,"security":"critical","strictest":false,"type":"boolean","user_choice_allowed":false,"watch_limit":"ordered"},{"boundaries":[{"boundary":"guest","cap":false,"reason":"boundary_guest"},{"boundary":"child_protection","cap":false,"reason":"boundary_child_protection"}],"default":false,"default_fixed":false,"default_user_choice":false,"enforcement":"app","enforcement_with_checked_path":null,"enforcement_with_hub_path":null,"fixed_checkbox":true,"group":"access","help":{"de":"Zeigt am Gerät den Schalter „Unverschlüsselt immer erlauben (weniger sicher)“. Er ist dort anfangs aus.","en":"Shows the switch “Always allow unencrypted (less secure)” on the device. It starts off there."},"key":"connection_insecure_http","label":{"de":"Darf Unverschlüsselt immer erlauben","en":"May always allow unencrypted"},"loosening_warning":{"de":"Das Gerät schickt seinen Zugang zu Home Assistant dann auch unverschlüsselt in Netze, die nicht als Heimnetz bestätigt sind. Ein anderes WLAN mit derselben Adresse kann ihn mitlesen.","en":"The device then also sends its Home Assistant access unencrypted into networks not confirmed as the home network. Another Wi-Fi network that uses the same address can read it."},"order":[false,true],"platforms":["ios","ipados","tvos","android","android_tablet","android_tv"],"prerequisite":null,"pro":false,"profile_kinds":null,"replaces":[],"requires_child_protection":false,"security":"critical","strictest":false,"type":"boolean","user_choice_allowed":false,"watch_limit":"ordered"},{"boundaries":[{"boundary":"guest","cap":"checked","reason":"boundary_guest"},{"boundary":"child_protection","cap":"checked","reason":"boundary_child_protection"}],"default":"checked","default_fixed":false,"default_user_choice":false,"enforcement":"ha","enforcement_with_checked_path":null,"enforcement_with_hub_path":"hub","fixed_checkbox":true,"group":"access","help":{"de":"Nur über den Hub: Das Gerät bekommt keinen Home-Assistant-Schlüssel. Es liest und schaltet nur über den Hub und sieht nur, was dieses Profil erlaubt; es funktioniert dort, wo der Hub erreichbar ist (zu Hause). Mit Fernzugriff bekommt es einen Schlüssel, der nur lesen darf (siehe dort). Geprüft: ein Schlüssel, der nur lesen darf; geschaltet wird nur über die geprüfte Aktion von {brand}, lesen kann das Gerät aber jeden Zustand in Home Assistant. Direkt: volle Rechte in Home Assistant; die Regeln gelten nur in {brand}.","en":"Hub only: the device gets no Home Assistant key. It reads and switches only through the hub and sees only what this profile allows; it works where the hub is reachable (at home). With remote access it gets a read-only key (see there). Checked: a read-only key; it switches only through the checked action of {brand}, but can read every state in Home Assistant. Direct: full rights in Home Assistant; the rules apply only in {brand}."},"key":"control_path","label":{"de":"Zugang zu Home Assistant","en":"Home Assistant access"},"loosening_warning":{"de":"Geprüft: Das Gerät bekommt einen Home-Assistant-Schlüssel, der nur lesen darf, und kann jeden Zustand in Home Assistant lesen, auch was dieses Profil ausblendet. Direkt: Wer seinen Schlüssel hat, kann an {brand} vorbei alles schalten.","en":"Checked: the device gets a read-only Home Assistant key and can read every state in Home Assistant, also what this profile hides. Direct: whoever holds its key can switch everything past {brand}."},"order":["hub","checked","direct"],"platforms":["ios","ipados","tvos","watchos","android","android_tablet","android_tv","wearos"],"prerequisite":null,"pro":false,"profile_kinds":null,"replaces":[],"requires_child_protection":false,"security":"critical","strictest":"hub","type":"enum","user_choice_allowed":false,"watch_limit":"ordered"},{"boundaries":[],"default":{"enabled":false,"windows":[]},"default_fixed":false,"default_user_choice":false,"enforcement":"app","enforcement_with_checked_path":"ha_control","enforcement_with_hub_path":"hub","fixed_checkbox":true,"group":"access","help":{"de":"Das Gerät hat nur in diesen Zeiten Zugang. Ausserhalb bleibt es gekoppelt, sieht aber nichts. Zusätzlich gibt es in Home Assistant einen Schalter „Zugang“ für eigene Zeitpläne.","en":"The device has access only at these times. Outside them it stays paired but sees nothing. Home Assistant also gets an “Access” switch for your own schedules."},"key":"access_hours","label":{"de":"Zugangszeiten","en":"Access hours"},"loosening_warning":{"de":"Das Gerät hat dann zu mehr Zeiten Zugang zu deinem Zuhause.","en":"The device then has access to y